(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["microbiology-exam-3"]={"title":"Microbiology Exam 3","sections":[{"id":"crit-l15-dimorphism","title":"Thermal DimorphismTable · Lecture 15 · slides 5–6","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"crit-l15-levels","title":"Levels of Fungal Infection, Shallow to DeepClassification · Lecture 15 · slides 14, 22–23, 38, 42, 49","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"crit-l15-who","title":"World Health Organization Fungal Priority Pathogens List (2022)Classification · Lecture 15 · slides 10–11, 56, 60","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"crit-l15-true","title":"The Four True (Dimorphic) Fungal PathogensComparison · Lecture 15 · slides 13, 26–37","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"crit-l15-tinea","title":"Tinea by Body Site: the Latin Names★ Classification · Lecture 15 · slides 43–45 (“Focus on the Latin names”)","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"crit-l15-superficial","title":"Superficial MycosesClassification · Lecture 15 · slides 49–50","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"crit-l15-opportunists","title":"Opportunists and What Predisposes to Them (Table 22.3)Table · Lecture 15 · slide 9","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"crit-l15-treatment","title":"Treatments Named on the SlidesComparison · Lecture 15 · slides 19–20, 26–63","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"crit-l15-toxins","title":"Fungal Toxins (Mycotoxicoses)Classification · Lecture 15 · slide 65","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"crit-l16-effects","title":"What Microbes Do to FoodClassification · Lecture 16 · slide 3","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"crit-l16-bread","title":"Bread Making: the Three Jobs of MicrobesList · Lecture 16 · slide 4","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"crit-l16-intox","title":"Food Intoxication versus Food InfectionClassification · Lecture 16 · slide 12","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"crit-l16-bacteria","title":"The Seven Foodborne BacteriaComparison · Lecture 16 · slides 13–29","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"crit-l16-bcereus","title":"Bacillus cereus: Two FormsClassification · Lecture 16 · slide 28","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"crit-l16-viruses","title":"Foodborne VirusesComparison · Lecture 16 · slide 33","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"crit-l16-agencies","title":"Who Watches the Food SupplyClassification · Lecture 16 · slides 9, 34–35","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"crit-l16-numbers","title":"The Numbers on the SlidesCut-offs · Lecture 16 · slides 21, 23, 28, 33, 36","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l14-scope","title":"L14 · What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-endotoxin-sorting","title":"L14 · Endotoxin & Sorting","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-pseudomonas","title":"L14 · Pseudomonas & Its Relatives","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-zoonoses-human","title":"L14 · Brucella, Francisella, Bordetella, Legionella","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-enterics","title":"L14 · The Enterics: Traits, Media, Antigens","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-ecoli","title":"L14 · Escherichia coli Pathotypes","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-coliforms-proteus","title":"L14 · Other Coliforms & Proteus","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-salmonella-shigella","title":"L14 · Salmonella, Shigella, Enteric Yersinia","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-plague","title":"L14 · Yersinia pestis & Plague","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l14-pasteurella-haemophilus","title":"L14 · Pasteurella & Haemophilus","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l14-transmission","title":"L14 · Objective 2: How We Get Them","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l15-pathogens","title":"L15 · Fungi as Pathogens","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l15-dx-control","title":"L15 · Diagnosis & Control","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l15-true","title":"L15 · The True Pathogens (Systemic)","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l15-skin","title":"L15 · Subcutaneous, Cutaneous, Superficial","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l15-opportunists","title":"L15 · The Opportunists","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l15-allergy-transmission","title":"L15 · Allergies, Toxins & How We Get Them","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l16-food-microbes","title":"L16 · Microbes in Food","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l16-burden","title":"L16 · The Problem & the First Split","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l16-enteric","title":"L16 · E. coli, Salmonella, Campylobacter","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l16-others","title":"L16 · Listeria, Clostridium, B. cereus, Vibrio","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l16-nonbacterial","title":"L16 · Protozoa, Worms, Viruses","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l16-tracking","title":"L16 · Tracking, Objective 3, Prevention","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"}],"rows":[{"t":"Mold (multicellular, hyphae)","d":"30 °C (slide 6: below 30 °C)</td><td>Natural habitat; saprobic (free-living), mycelial phase; reproduces by sporulation","s":0},{"t":"Yeast (unicellular)","d":"37 °C, body temperature (slide 6: 35–40 °C)</td><td>Animal habitat; parasitic, yeast phase; reproduces by budding or endospores","s":0},{"t":"Superficial","d":"Extremely shallow epidermal colonization</td><td>Contamination of the skin or hair surface</td><td>Tinea versicolor, white and black piedra","s":1},{"t":"Cutaneous","d":"Stratum corneum, occasionally the upper dermis (keratin only)</td><td>Contamination of the skin or hair surface</td><td>The dermatophytes: ringworm, tinea","s":1},{"t":"Subcutaneous","d":"Subcutaneous tissue, after a puncture wound</td><td>Inoculated into skin or nails: trauma</td><td>Sporothrix schenckii","s":1},{"t":"Systemic (primary)","d":"From the lungs into the circulation: brain, kidneys, other organs</td><td>Respiratory: spores inhaled from the air</td><td>Histoplasma, Coccidioides, Blastomyces, Paracoccidioides","s":1},{"t":"Critical","d":"Cryptococcus neoformans (number one, slide 56) · Aspergillus fumigatus (number three, slide 60) · Candida albicans · Candida auris","s":2},{"t":"High","d":"Other Candida species · Eumycetoma causative agents · Fusarium species · Histoplasma species · Mucorales (mucormycosis opportunists)","s":2},{"t":"Medium","d":"Coccidioides · Cryptococcus gattii · Pneumocystis jirovecii · Paracoccidioides species","s":2},{"t":"Histoplasma capsulatum (Ohio Valley fever)","d":"Eastern and central United States; Latin America, Africa</td><td>Moist, nitrogen-rich soil with bird and bat guano</td><td>Most common true pathogen; NOT person to person; yeast multiplies inside phagocytes","s":3},{"t":"Coccidioides immitis (Valley fever)","d":"Southwestern United States, Mexico, Central and South America</td><td>Alkaline, salty soil of semiarid, hot climates; dust</td><td>Arthroconidia in soil, spherules with endospores in the lungs; most need no treatment","s":3},{"t":"Blastomyces dermatitidis (North American blastomycosis)","d":"Midwestern and southeastern United States, southern Canada; also reported in South and Central America, Africa, the Middle East</td><td>Forest soil, decaying wood, animal manure</td><td>May be mistaken for lung cancer on chest X-ray; skin nodules, later bone and nervous system","s":3},{"t":"Paracoccidioides brasiliensis (paracoccidioidomycosis)","d":"Central and South America (Brazil, Colombia, Venezuela, Argentina, Paraguay)</td><td>Cool, humid soil; inhaled (lung) or inoculated (skin)</td><td>The rarest primary mycosis; rural farm workers, poor nutrition; usually mild, self-limiting","s":3},{"t":"Tinea capitis","d":"Scalp</td><td>Scalp and hair-bearing head; hair may be lost; common in children","s":4},{"t":"Tinea barbae","d":"Beard</td><td>Chin and beard of adult males; mainly from animals","s":4},{"t":"Tinea corporis","d":"Body</td><td>Inflamed, red ring lesions on smooth skin; contact, clothing, bedding","s":4},{"t":"Tinea cruris","d":"Groin</td><td>'Jock itch': groin and scrotum; athletes, crowded living","s":4},{"t":"Tinea pedis","d":"Foot</td><td>Public surfaces; between the digits and on the soles; rare where people go barefoot","s":4},{"t":"Tinea manuum","d":"Hand</td><td>Paired with tinea pedis: public surfaces, between the digits","s":4},{"t":"Tinea unguium","d":"Nails</td><td>Persistent colonization that distorts the nail bed; nail extensions a portal of entry","s":4},{"t":"Tinea versicolor","d":"Malassezia furfur (a yeast)</td><td>Mild, chronic scaling and mottling of the skin; also folliculitis, psoriasis, seborrheic dermatitis","s":5},{"t":"White piedra","d":"Trichosporon species</td><td>Whitish or colored masses on pubic or axillary hair (also body, beard, mustache, eyebrows)","s":5},{"t":"Black piedra","d":"Piedraia species</td><td>Dark-brown to black gritty nodules, mainly on scalp hairs","s":5},{"t":"Candida","d":"Antibiotic therapy, catheters, diabetes, corticosteroids, immunosuppression","s":6},{"t":"Aspergillus","d":"Leukemia, corticosteroids, tuberculosis, immunosuppression, intravenous drug abuse","s":6},{"t":"Cryptococcus","d":"Diabetes, tuberculosis, cancer, corticosteroids, immunosuppression","s":6},{"t":"Zygomycota species","d":"Diabetes, cancer, corticosteroids, intravenous therapy, third-degree burns","s":6},{"t":"Histoplasmosis","d":"Amphotericin B and azoles","s":7},{"t":"Coccidioidomycosis","d":"Amphotericin B, but most cases need no treatment","s":7},{"t":"Blastomycosis","d":"Amphotericin B","s":7},{"t":"Paracoccidioidomycosis","d":"Ketoconazole, amphotericin B, sulfa drugs","s":7},{"t":"Sporotrichosis","d":"Heat packs, super-saturated potassium iodide; systemic: amphotericin B and/or itraconazole","s":7},{"t":"Dermatophytoses (tinea)","d":"Topical azoles for several weeks, oral antifungals if needed; debridement; ultraviolet light","s":7},{"t":"Candidiasis","d":"Topical antifungals (superficial); amphotericin B and azoles (systemic)","s":7},{"t":"Cryptococcosis","d":"Amphotericin B and fluconazole or another azole","s":7},{"t":"Pneumocystis pneumonia","d":"Pentamidine (anti-protozoan) and co-trimoxazole (antibacterial): NOT traditional antifungals","s":7},{"t":"Mucormycosis","d":"Removal of affected tissue and amphotericin B","s":7},{"t":"Eumycetoma","d":"Long-term antifungal drug therapy and amputation may be required","s":7},{"t":"Aflatoxin","d":"Grains, corn, peanuts</td><td>Hepatotoxic and carcinogenic; lethal to poultry and livestock (turkeys, ducklings, pigs, calves); may be a co-factor in human liver cancer","s":8},{"t":"Ergot","d":"Rye and other grains contaminated by Claviceps</td><td>Mind-altering lysergic acid (cross-reference Salem, Massachusetts)","s":8},{"t":"Stachybotrys chartarum","d":"Damp buildings</td><td>Sick building syndrome ('black mold', not mucormycosis); can cause severe hematologic and neurological damage","s":8},{"t":"Beneficial","d":"Food fermented or chemically changed by added microbes or microbial products, to alter or improve flavor, taste or texture","s":9},{"t":"Detrimental","d":"Food poisoning, food intoxication, food-borne illness and food spoilage (undesirable flavor, appearance or smell)","s":9},{"t":"Neutral","d":"Microbes present that neither cause disease nor change the food; eaten along with it","s":9},{"t":"1. Leavening","d":"Raises flour-based dough, mainly with carbon dioxide and other gases","s":10},{"t":"2. Flavor and aroma","d":"Organic acids and alcohols","s":10},{"t":"3. Conditioning","d":"Microbial enzymes act on gluten: elastic, pliable, workable dough","s":10},{"t":"What is eaten","d":"A preformed toxin (cells and toxin in the food)</td><td>Live bacterial cells","s":11},{"t":"What happens","d":"The toxin reaches its target organs</td><td>Improper cooking; bacteria multiply in the food, then an intestinal infection","s":11},{"t":"Examples","d":"Staphylococcal toxin; Clostridium botulinum toxin</td><td>Salmonella; Listeria","s":11},{"t":"Escherichia coli","d":"Human and animal feces; contaminated meats and vegetables</td><td>The fecal INDICATOR organism; eosin methylene blue plates confirm it; O157:H7 among the worst","s":12},{"t":"Salmonella","d":"Poultry and aquatic reptiles; eggs, pet food, peanut butter, produce</td><td>Young children and the elderly at greatest risk; typhoid the most severe enteric fever","s":12},{"t":"Campylobacter jejuni","d":"Raw poultry (one drop of its fluid)</td><td>Infectious dose under 500 cells; bloody diarrhea; a leading United States bacterial diarrhea","s":12},{"t":"Listeria monocytogenes","d":"Birds, mammals, soil; soft cheese, deli meats, hot dogs, produce</td><td>Grows from 1 to 40 °C; pregnant women and the fetus; slide: number one cause of food-related deaths in the United States","s":12},{"t":"Clostridium (botulinum)","d":"Spores in soil, on plants, in honey</td><td>Toxin when spores germinate; flaccid ('relaxed') paralysis, respiratory failure","s":12},{"t":"Bacillus cereus","d":"Rice (emetic form), meat (diarrheal form)</td><td>Very common in summer; onset in 6 hours or less, self-resolving","s":12},{"t":"Vibrio","d":"Salt water: ocean and estuaries; shellfish, oysters, crabs</td><td>Water route (including wound infection) or food route","s":12},{"t":"Diarrheal","d":"Heat-stable toxin</td><td>Meat","s":13},{"t":"Emetic (vomiting)","d":"Heat-labile toxin</td><td>Rice","s":13},{"t":"What it is","d":"Norwalk-like virus, family Caliciviridae; a common foodborne agent</td><td>The hepatitis viruses typically spread by the fecal-oral route","s":14},{"t":"Spread","d":"Person to person by feces and vomitus (daycares, nursing homes, cruise ships); contaminated shellfish</td><td>Fecal-oral; NOT by kissing, sneezing, saliva or blood","s":14},{"t":"Course","d":"A few viral particles infect; rapid onset and short duration: nausea, vomiting, diarrhea, low-grade fever</td><td>Most contagious about two weeks BEFORE symptoms","s":14},{"t":"Surveillance and outbreak investigation","d":"Local and state health departments, Centers for Disease Control and Prevention, Food and Drug Administration, United States Department of Agriculture","s":15},{"t":"Food safety law enforcement and policy","d":"Food and Drug Administration and United States Department of Agriculture","s":15},{"t":"PulseNet (pulsed-field gel electrophoresis patterns)","d":"Centers for Disease Control and Prevention","s":15},{"t":"Recall information","d":"Food and Drug Administration (food, dietary supplements, pet food); United States Department of Agriculture","s":15},{"t":"1 to 40 °C","d":"The range Listeria grows in: refrigerator, room and freezer temperatures (slide 23)","s":16},{"t":"Under 500 cells","d":"The Campylobacter infectious dose: one drop of raw poultry fluid (slide 21)","s":16},{"t":"6 hours or less","d":"Bacillus cereus onset (slide 28)","s":16},{"t":"About 2 weeks before symptoms","d":"When hepatitis A or E is most contagious (slide 33)","s":16},{"t":"165 °F","d":"The meat thermometer reading (slide 36; see guide 16.17)","s":16},{"t":"★ The four E. coli strains","d":"“There are four different strains of E. coli that you need to know. Hint, hint, hint, hint.” ENTEROTOXIGENIC (traveler's diarrhea) · ENTEROINVASIVE (no toxins, shigellosis-like) · ENTEROPATHOGENIC (infant wasting diarrhea, microvilli) · ENTEROHEMORRHAGIC O157:H7 (Shiga toxin, hemolytic uremic syndrome).","s":17},{"t":"★ Cystic fibrosis","d":"Pseudomonas aeruginosa: “very, very, very common with cystic fibrosis patients” (the slide's own star). Burkholderia cepacia with it = 80% fatality.","s":17},{"t":"★ Endotoxin","d":"“Any gram-negative organism will have that weapon.” Lipid A; released on lysis, so killing them with antibiotics can make the patient feel worse first.","s":17},{"t":"No drug questions","d":"“I'm not going to be testing on which antibiotics.” Non-drug management (fluids, dialysis, plasmapheresis, vaccines, breast feeding, quarantine) is fair game.","s":17},{"t":"Not to memorize","d":"Slide 8's endotoxin diagram · slide 19's body map of Pseudomonas infections (“it can hit you pretty much anywhere”) · percentages · slide 47's biochemical tree.","s":17},{"t":"Association only","d":"Proteus and bladder/kidney stones: “association, not causation.”","s":17},{"t":"Where the time went","d":"E. coli ~17 min · Pseudomonas 14 · plague 12 · endotoxin 10 · enterics 9 · Salmonella 9 · pertussis 8 · Legionella 8 (mostly outbreaks). One transcript only; she corrected no slide.","s":17},{"t":"Endotoxin","d":"LIPOPOLYSACCHARIDE of the outer membrane. LIPID A = biologically active part. Released on LYSIS (including by antibiotics) and during rapid growth.","s":18},{"t":"Three parts","d":"Lipid A (active) · core polysaccharide (same for large groups) · O antigen (unique per organism; repeat number = rough, semi-rough, smooth).","s":18},{"t":"Usually protective","d":"Innate immunity via a lipopolysaccharide binding complex + Toll-like receptor → moderated inflammation keeps mucosal infection mucosal.","s":18},{"t":"Damaging","d":"Complement (hemorrhagic necrosis) · coagulation (disseminated intravascular coagulation, bradykinin) · high levels impair neutrophil CHEMOTAXIS · macrophages release tumor necrosis factor, interleukins 1 and 6.","s":18},{"t":"Low vs flood","d":"Low: fever, malaise, aches. Flood: SEPTIC SHOCK — microthrombi, vasodilation, cardiac output first UP (warm shock), then down → organ failure.","s":18},{"t":"Three sorting properties","d":"OXYGEN requirement · LACTOSE fermentation · OXIDASE enzyme.","s":18},{"t":"Aerobes, no fermentation","d":"Pseudomonas, Burkholderia, Bordetella, Francisella, Brucella, Alcaligenes. Pairs: Pseudomonas + Burkholderia OPPORTUNISTS · Brucella + Francisella ZOONOTIC · Bordetella + Legionella HUMAN.","s":18},{"t":"Facultative anaerobes","d":"Lactose + (coliforms): Escherichia, Klebsiella, Citrobacter, Enterobacter. Lactose −, oxidase −: Salmonella, Shigella, Proteus, Yersinia and others. Lactose −, OXIDASE +: Haemophilus, Pasteurella. Obligate anaerobe: Bacteroides.","s":18},{"t":"Pseudomonads","d":"Small rods, ONE POLAR flagellum · aerobic, NO fermentation · oxidase + catalase + · water-soluble pigments · soil and water.","s":19},{"t":"P. aeruginosa signs","d":"GRAPELIKE odor · greenish-blue pigment PYOCYANIN · resists soaps, quaternary ammonium disinfectants, drying.","s":19},{"t":"Why hospitals","d":"BIOFILMS → contaminates ventilators, intravenous solutions, anesthesia equipment. Major nosocomial agent.","s":19},{"t":"Virulence","d":"Exotoxin A blocks PROTEIN SYNTHESIS · slime layer (anti-phagocytosis, biofilm) · exoenzyme S → T cell APOPTOSIS · multidrug resistant (permeability, enzymes, efflux pumps, gene transfer).","s":19},{"t":"Disease","d":"★ Burns, neoplastic disease, CYSTIC FIBROSIS. Septicemia → endocarditis, meningitis. Healthy people: rash, urinary tract infection, SWIMMER'S EAR, CORNEAL ULCER (contact lenses).","s":19},{"t":"Vaccine","d":"In development, for cystic fibrosis; but in CHRONIC cystic fibrosis infection it may worsen lung inflammation.","s":19},{"t":"Relatives","d":"Obligate aerobes, no sugar fermentation, opportunists. B. cepacia: cystic fibrosis copathogen, mutates fast. B. pseudomallei: MELIOIDOSIS, tropical soil, injury or inhalation. A. baumannii: MONTHS on fomites, combat wounds. S. maltophilia: biofilms on equipment.","s":19},{"t":"Brucella","d":"Tiny coccobacilli. B. abortus (CATTLE), B. suis (PIGS). Malta / UNDULANT / Bang fever: fever fluctuating weeks to a year. Slaughtering, placentas, UNPASTEURIZED dairy. Agglutination titer. ANIMAL vaccine.","s":20},{"t":"Francisella tularensis","d":"TULAREMIA, rabbit fever. Animals, water and dust, vector bites; 10–50 organisms. Ulcerative skin lesion + swollen nodes. Intracellular → RELAPSE. Attenuated vaccine.","s":20},{"t":"Bordetella pertussis","d":"Minute encapsulated coccobacillus. Healthy CARRIERS; contact or aerosols. Binds and destroys CILIATED cells → mucus blocks airways.","s":20},{"t":"Pertussis stages","d":"CATARRHAL (drainage, sneezing, occasional cough) → PAROXYSMAL (persistent cough + the WHOOP).","s":20},{"t":"Pertussis prevention","d":"DTaP (diphtheria, tetanus and acellular pertussis): ACELLULAR, toxoid + antigens, 5 doses 2 months–6 years. Rising: infants under 2 months unvaccinable · WANING immunity · pertactin-negative strains.","s":20},{"t":"Legionella","d":"WEAKLY Gram negative, pleomorphic. Hard to culture: CHARCOAL YEAST EXTRACT agar. Lives with AMEBAS in water. AEROSOLS (cooling towers, fountains). Legionnaires disease, Pontiac fever. Men over 50, smokers, nosocomial elderly.","s":20},{"t":"Family traits","d":"Small non-spore-forming rods · FACULTATIVE anaerobes · ALL ferment GLUCOSE · nitrate → nitrite · OXIDASE − · catalase + · all have O antigen.","s":21},{"t":"Coliform vs not","d":"COLIFORMS ferment LACTOSE; non-coliforms do not.","s":21},{"t":"Two kinds of diarrhea","d":"TOXIGENIC: on the surface, oversecretion of fluid (enterotoxigenic E. coli). INVASIVE: enter the lining, bleeding (Shigella).","s":21},{"t":"Media","d":"EMB (eosin methylene blue) and MacConkey's (crystal violet + BILE SALTS): both SELECTIVE for Gram negatives, DIFFERENTIAL for lactose fermenters (pink on MacConkey's).","s":21},{"t":"Antigens","d":"H = FLAGELLAR · K = CAPSULE/fimbrial (Vi in Salmonella) · O = SOMATIC cell wall, all have it.","s":21},{"t":"Hospitals","d":"With Pseudomonas, almost HALF of nosocomial infections; soap dishes, sinks, catheters, tracheal cannulas.","s":21},{"t":"E. coli","d":"Common AEROBIC gut bacterium, but NOT the most prevalent (anaerobic Bacteroides, Bifidobacterium are). Virulence by PLASMID transfer.","s":22},{"t":"Enterotoxigenic","d":"Heat-labile + heat-stable TOXINS → fluid secretion; fimbriae, SMALL intestine. TRAVELER'S DIARRHEA. Fluids; bismuth salicylate counters the toxin.","s":22},{"t":"Enteroinvasive","d":"NO toxins, mechanical damage; LARGE intestine, like SHIGELLOSIS. Bloody diarrhea, high fever.","s":22},{"t":"Enteropathogenic","d":"Adheres and destroys MICROVILLI. Wasting INFANTILE diarrhea, top infant killer worldwide. Prevention: BREAST FEEDING.","s":22},{"t":"Enterohemorrhagic O157:H7","d":"SHIGA toxin binds RIBOSOMES. CATTLE reservoir: beef, water, vegetables; ~100 cells. Hemorrhagic colitis, HEMOLYTIC UREMIC SYNDROME. RAINBOW agar: BLACK colonies (glucuronidase −). Antibiotics may WORSEN it; dialysis, plasmapheresis.","s":22},{"t":"Outside the gut","d":"Most URINARY TRACT INFECTIONS (women, catheters) · neonatal meningitis · COLIFORM COUNT = fecal contamination of water.","s":22},{"t":"Klebsiella pneumoniae","d":"Normal RESPIRATORY flora · LARGE CAPSULE · NOSOCOMIAL PNEUMONIA.","s":23},{"t":"Serratia marcescens","d":"RED pigment PRODIGIOSIN · pneumonia in chronic ALCOHOLICS, burns, urinary tract infections.","s":23},{"t":"Enterobacter · Citrobacter","d":"Opportunistic urinary tract, wound and bloodstream infections.","s":23},{"t":"Proteus","d":"HIGHLY MOTILE, peritrichous flagella → SWARMING waves. Urinary tract infection, bladder and KIDNEY STONES, Crohn's disease.","s":23},{"t":"Providencia · Morganella","d":"Providencia: multiple ANIMAL reservoirs, CATHETER urinary infections. Morganella: like Proteus. Both multidrug resistant.","s":23},{"t":"Salmonella typhi","d":"HUMANS the only host · resists BILE and dyes · fecal food or water (“boil it, cook it, peel it, or forget it”) · chronic GALLBLADDER carriers.","s":24},{"t":"Typhoid course","d":"SMALL intestine → invasive → SEPTICEMIA → liver, spleen; ulceration, PERFORATION. Sustained fever 103–104, ROSE SPOTS. Vaccines: oral (4 doses), injected (1).","s":24},{"t":"Animal salmonelloses","d":"Less severe than typhoid but MORE PREVALENT. Ingestion: POULTRY and EGGS, cattle, REPTILES (pet turtles), backyard flocks. S. cholerae-suis = swine.","s":24},{"t":"Shigella","d":"Fecal food → invades LARGE-intestine villi; does NOT perforate or enter the blood. ENDOTOXIN → fever; ENTEROTOXIN → mucosal damage, blood and mucus. Dysentery; under-5s.","s":24},{"t":"Enteric yersinias","d":"Y. enterocolitica: animals, fish, produce, water; ILEUM inflammation MIMICS APPENDICITIS. Y. pseudotuberculosis: MORE lymph node inflammation.","s":24},{"t":"Organism","d":"Tiny rod, BIPOLAR staining, capsule · COAGULASE, endotoxin, murine toxin. ~200 rodent reservoirs; United States cases WEST of the Mississippi.","s":25},{"t":"The flea","d":"Coagulase CLOTS block the flea's esophagus → RAVENOUS, bites again → REGURGITATES bacteria into the bite. 3–50 bacilli.","s":25},{"t":"Sylvatic vs urban","d":"SYLVATIC = wild animals · URBAN = domestic or semidomestic animals · human to human rare.","s":25},{"t":"Three forms","d":"BUBONIC: lymph node necrosis, the BUBO (groin, axilla) · SEPTICEMIC: purpura → gangrene, the BLACK plague · PNEUMONIC: lungs, highly contagious by AEROSOL.","s":25},{"t":"Diagnose fast","d":"Death within 2 days of symptoms. History, symptoms, ASPIRATE THE BUBO. Killed or attenuated vaccine (military, vets, lab). QUARANTINE + rodent control.","s":25},{"t":"Pasteurella multocida","d":"OXIDASE +; zoonotic, normal ANIMAL flora. Animal BITES or SCRATCHES → local abscess → joints, bones, nodes. Veterinarians; septicemia if immunocompromised.","s":26},{"t":"Haemophilus","d":"“Blood loving,” fastidious. CHOCOLATE agar (cooked blood): needs HEMIN, nicotinamide adenine dinucleotide (NAD) or its phosphate.","s":26},{"t":"H. influenzae","d":"MISNAMED (not the flu). MENINGITIS, EPIGLOTTITIS, otitis media, sinusitis, pneumonia. SUBUNIT vaccine Hib (Haemophilus influenzae type b).","s":26},{"t":"Other species","d":"H. aegyptius: PINK EYE, children, fingers and insects · H. ducreyi: CHANCROID, sexually transmitted · H. parainfluenzae, H. aphrophilus: oral flora → ENDOCARDITIS after dental work.","s":26},{"t":"Water, soil, equipment","d":"Pseudomonas (biofilms on ventilators, intravenous lines) · B. pseudomallei (injury, inhalation) · Acinetobacter (fomites) · Stenotrophomonas (biofilms).","s":27},{"t":"Animals","d":"Brucella (slaughter, unpasteurized dairy) · Francisella (rabbits, water, dust, vectors) · O157:H7 (cattle) · animal salmonelloses (poultry, eggs, reptiles) · Pasteurella (bites) · plague (fleas, rodents).","s":27},{"t":"Air","d":"Bordetella (carriers, aerosols) · Legionella (water aerosols) · pneumonic plague (aerosol).","s":27},{"t":"Fecal-oral","d":"E. coli diarrheal strains, Salmonella typhi (humans only), Shigella.","s":27},{"t":"Self and partner","d":"E. coli urinary tract infection (women, catheters) · H. parainfluenzae (own oral flora, dental work) · H. ducreyi (sexual) · H. aegyptius (fingers, insects).","s":27},{"t":"True (primary) pathogen","d":"Invades and grows in a HEALTHY host. Can cause systemic, subcutaneous, cutaneous and superficial mycoses. The four true pathogens are thermally dimorphic.","s":28},{"t":"Opportunist","d":"Little or no virulence of its own; needs IMPAIRED defenses (human immunodeficiency virus infection, cancer, diabetes, chronic obstructive pulmonary disease, autoimmune disorder, nosocomial). Once 'harmless' skin or air contaminants.","s":28},{"t":"Thermal dimorphism","d":"MOLD (multicellular) at 30 °C in soil → YEAST (unicellular) at 37 °C in the body. The true pathogen's key adaptation.","s":28},{"t":"Mostly harmless","d":"Relatively nonpathogenic: ~300 of ~100,000 species cause disease. But fungi are the most common PLANT pathogens (potato blights, famines).","s":28},{"t":"Emerging","d":"Mycoses ~10% of nosocomial infections and rising; dermatophytes may be becoming true pathogens; invasive fungal disease rising in the immunocompromised.","s":28},{"t":"Host defense","d":"Skin, mucous membranes, cilia; MOST IMPORTANT = cell-mediated immunity (T cells, cytokines), phagocytosis, inflammation. Reinfection highly likely with opportunists.","s":28},{"t":"Communicable?","d":"Most fungal infections are NOT (no host needed for the life cycle). Exceptions: dermatophytes and Candida (person to person, fomites).","s":28},{"t":"Most prevalent","d":"Dermatophytoses: the most common fungal diseases; often undiagnosed or misdiagnosed as allergy or autoimmune disease.","s":28},{"t":"Diagnosis","d":"Microscopy of stained specimens + culture on selective and enriched media + biochemical or serological tests.","s":29},{"t":"Sabouraud dextrose agar","d":"Commonly used; its LOW pH inhibits most bacteria but not fungi (chemicals added to block bacteria).","s":29},{"t":"Potassium hydroxide","d":"Lyses human epithelial cells, leaves fungi intact: fungi have a THICKER cell wall.","s":29},{"t":"Flowchart clues","d":"Wood's light on hairs · negative stain for a capsule · GERM TUBE test (yeasts in serum 2–4 h sprout hyphal tubes) · culture at 25–30 °C AND 37 °C to demonstrate dimorphism · long incubations (up to 8 weeks; 4 weeks for hair, skin, nails) · animal inoculation only when other methods fail.","s":29},{"t":"Stains (slide 18)","d":"Aspergillus = BRANCHED SEPTATE hyphae in sputum; germinating Candida albicans = young hypha from a yeast.","s":29},{"t":"No vaccines","d":"Immunization typically ineffective because REINFECTION is exceedingly common.","s":29},{"t":"Control","d":"Drugs: amphotericin B, flucytosine, azoles, nystatin · surgical removal of damaged tissue · prevention = respirator masks, protective clothing, hygiene.","s":29},{"t":"Amphotericin B","d":"Drug of choice for many infections; from Streptomyces (a soil bacterium); complexes with fungal membrane LIPIDS → leakage; TOXIC because fungi and humans are both eukaryotes (fatigue, weakness, fever, arrhythmia): 'ampho-terrible'.","s":29},{"t":"Shared pattern","d":"Endemic regions; soil or animal waste with conidia is DISTURBED → spores INHALED → yeasts in the lungs → may go systemic; can also inoculate broken skin.","s":30},{"t":"Histoplasma capsulatum","d":"OHIO VALLEY FEVER; the MOST COMMON true pathogen; eastern/central United States, Latin America, Africa; moist nitrogen-rich soil with BIRD AND BAT GUANO; inhaled microconidia; NOT person to person; yeast multiplies inside phagocytes; most recover.","s":30},{"t":"Coccidioides immitis","d":"VALLEY FEVER; southwestern United States to Mexico, Central/South America; alkaline, salty soil of semiarid, hot climates; dust (farming, construction, digs, dust storms); drought-rain-wind cycles; ARTHROCONIDIA → SPHERULES with endospores; risk: African descent, age 40–60+, dust exposure; most need no treatment.","s":30},{"t":"Blastomyces dermatitidis","d":"NORTH AMERICAN blastomycosis; forest soil, decaying wood, manure; Midwest/Southeast and southern Canada; inhaled conidia → yeasts; MIMICS LUNG CANCER on chest X-ray; dogs, cats, horses; chronic skin nodules, later bone and nervous system.","s":30},{"t":"Paracoccidioides brasiliensis","d":"Central/South America (Brazil); the RAREST primary mycosis; inhalation (lung) or inoculation (skin); rural farm workers, poor nutrition, male, over 40; usually mild, self-limiting.","s":30},{"t":"Subcutaneous mycoses","d":"Fungus pushed into TRAUMATIZED skin; inhibited by the warmth of blood and viscera, so rarely disseminate; progressive tissue destruction.","s":31},{"t":"Sporothrix schenckii","d":"ROSE-GARDENER'S disease: thorn, wood, bare roots; saprobe in soil; garden centers, nurseries, pine straw, hay; LYMPHOCUTANEOUS = nodule then spread to nearby lymph nodes; heat packs, super-saturated potassium iodide; systemic: amphotericin B and/or itraconazole.","s":31},{"t":"Dermatophytes","d":"Keratin ONLY (skin, hair, scalp, nails) = ringworm/tinea; Trichophyton, Microsporum, Epidermophyton (39 species); agent varies case to case; reservoirs humans, animals, soil; hardy spores + abraded skin + close contact or fomites; long infection, then inflammation and allergy to fungal proteins.","s":31},{"t":"★ Latin names","d":"The deck: 'Focus on the Latin names for each body part/region' → capitis, barbae, corporis, cruris, pedis, manuum, unguium (table above).","s":31},{"t":"Tinea treatment","d":"Topical AZOLES for several weeks ± oral antifungals; debridement; ultraviolet light.","s":31},{"t":"Superficial mycoses","d":"Tinea VERSICOLOR = Malassezia furfur, a YEAST (scaling, mottling). WHITE piedra = Trichosporon (pubic/axillary hair). BLACK piedra = Piedraia (scalp hairs). Piedras non-contagious, hygiene; rare in the United States.","s":31},{"t":"Candida albicans","d":"The DOMINANT opportunist; normal flora (mouth, genitalia, large intestine, skin); ~70% of nosocomial fungal infections; usually endogenous, but spread by surgery, childbirth, breast-feeding, sex; off-white pasty colony smelling of BAKING BREAD.","s":32},{"t":"Candida forms","d":"THRUSH (thick white adherent growth) · vulvovaginal (to unprotected partners, esp. uncircumcised males) · cutaneous in moist skin and burns · intertriginous (obesity). Diagnosis: budding yeast + PSEUDOHYPHAE; species by selective differential media.","s":32},{"t":"Candida auris","d":"Emerging invasive candidiasis; HOSPITAL OUTBREAKS hard to eradicate (drug resistant, thermoresistant, partly disinfectant resistant); first found in an EAR infection, Japan 2009.","s":32},{"t":"Cryptococcus neoformans","d":"#1 CRITICAL on the World Health Organization list; ENCAPSULATED yeast in soil around urban PIGEON roosts; healthy people resist; lungs → MENINGES and brain; NEGATIVE STAIN; serology and biochemistry best; amphotericin B + fluconazole.","s":32},{"t":"Pneumocystis jirovecii","d":"Unicellular fungus; the MOST PROMINENT opportunistic infection in acquired immunodeficiency syndrome; also kidney transplant; widespread silent exposure (antibody titers); secretions block breathing; PENTAMIDINE + CO-TRIMOXAZOLE (not antifungals); a fungus by genetics.","s":32},{"t":"Aspergillus fumigatus","d":"Airborne soil mold; azole resistance from CROP SPRAYING; #3 critical; lungs → FUNGAL BALLS; sinuses, ear canals, eyelids, conjunctiva; invasive necrotic pneumonia, brain, heart; leukemia, transplant, cystic fibrosis.","s":32},{"t":"Mucormycosis","d":"Zygomycota (Rhizopus, Mucor) saprobes; 'black mold' in India (steroids, uncontrolled DIABETES); nose, eyes, heart, brain in diabetes, leukemia, malnutrition; kwashiorkor gut form; cut out tissue + amphotericin B.","s":32},{"t":"Fusarium · eumycetoma","d":"Fusarium: tropical soil mold; contaminated CONTACT LENSES, toenails, burns. Eumycetoma: poor countries; male, 11–30, farmer, no shoes; long-term drugs, amputation.","s":32},{"t":"Allergies","d":"Spores → atopic allergy, seasonal allergy, asthma; farmer's lung, teapicker's lung, bark stripper's disease.","s":33},{"t":"Mycotoxicoses","d":"Ingested or inhaled fungal toxins: AFLATOXIN (liver, cancer co-factor; grains, corn, peanuts; kills turkeys) · ERGOT (rye, Claviceps, lysergic acid; Salem) · STACHYBOTRYS (sick building, 'black mold'; not mucormycosis).","s":33},{"t":"Objective 2: inhaled","d":"Systemic true pathogens (disturbed soil, guano, dust); Cryptococcus (pigeon roost soil); Aspergillus and Zygomycota (air).","s":33},{"t":"Objective 2: inoculated","d":"Sporothrix (thorns, wood); Paracoccidioides skin form; nail extensions (tinea unguium).","s":33},{"t":"Objective 2: contact","d":"Dermatophytes (people, animals, fomites, public surfaces; barbae mainly from animals) · Candida (surgery, birth, breast-feeding, sex; usually endogenous).","s":33},{"t":"Not communicable","d":"Most fungi; Histoplasma explicitly NOT person to person; piedras non-contagious.","s":33},{"t":"Three effects","d":"BENEFICIAL (fermentation improves flavor, taste, texture) · DETRIMENTAL (poisoning, intoxication, illness, spoilage) · NEUTRAL (just there, eaten with the food).","s":34},{"t":"Bread","d":"Leavening (carbon dioxide) · flavor and aroma (organic acids, alcohols) · conditioning (enzymes on gluten). Saccharomyces cerevisiae; some Clostridium; Lactobacillus sanfrancisco (sourdough).","s":34},{"t":"Beer and wine","d":"Glucose + yeast → 2 ethanol + 2 carbon dioxide. Brewing since 6000 BCE; malting, mashing, wort + hops, lagering, filtration. Wine from grapes or other fruit. Yeast source can be human SALIVA (chewed plant material).","s":34},{"t":"Pickling, soy","d":"Salt brine, lactic acid, vinegar, spices; soybeans → tofu, soy sauce; fish sauce, mole, tea, coffee.","s":34},{"t":"Milk","d":"STERILE until it exits the mammal; microbes from the body and milking UTENSILS; nutrient dense. First fermented dairy = accidental skin/nose/mouth microbes. Cheese: yeast, bacteria, molds. Yogurt: Lactobacillus + Streptococcus; kefir, koumiss, buttermilk.","s":34},{"t":"Microbes as food","d":"Spirulina (a cyanobacterium) in smoothies and gummies; single cell protein researched; feed additives already used for animals.","s":34},{"t":"Fungi in food","d":"Rarely cause disease; mushrooms, PENICILLIN, yeast fermentation; spoil bread, cereals, acidic juices.","s":34},{"t":"Scale","d":"~250 foodborne pathogens; BACTERIA most common; also viruses, parasites, microbial toxins; under-reported (slide figures: 75 million cases, 5000+ deaths).","s":35},{"t":"Who watches","d":"Surveillance + outbreak investigation: local/state health departments, Centers for Disease Control and Prevention, Food and Drug Administration, United States Department of Agriculture. ENFORCEMENT and policy: Food and Drug Administration + United States Department of Agriculture.","s":35},{"t":"Symptoms","d":"Diarrhea, abdominal cramps, nausea, fever, vomiting.","s":35},{"t":"Intoxication","d":"PREFORMED TOXIN eaten → target organs. Staphylococcal toxin, Clostridium botulinum toxin.","s":35},{"t":"Infection","d":"LIVE CELLS eaten; improper cooking lets them MULTIPLY in the food → intestinal infection. Salmonella, Listeria.","s":35},{"t":"The seven bacteria","d":"E. coli, Salmonella, Campylobacter jejuni, Listeria monocytogenes, Clostridium, Bacillus cereus, Vibrio.","s":35},{"t":"Escherichia coli","d":"FECAL INDICATOR organism (human and animal feces); EMB (eosin methylene blue) plates confirm it in food and water; not always pathogenic; toxin strains (enterotoxigenic, enterohemorrhagic); O157:H7 among the worst.","s":36},{"t":"E. coli outbreaks","d":"Fecally contaminated MEATS or VEGETABLES: hamburgers, bagged spinach, romaine lettuce, cookie dough, ground beef, raw milk cheese (western United States, 2026).","s":36},{"t":"Salmonella","d":"Animals, mainly POULTRY and AQUATIC REPTILES; gastroenteritis, enteric fever, septicemia, shock, kidney dysfunction; incubation HOURS to WEEKS; young children and the elderly at greatest risk.","s":36},{"t":"Typhoid fever","d":"Salmonella typhi: the MOST SEVERE enteric fever; invades the intestinal wall → blood and lymph nodes. 'Typhoid Mary' (Mary Mallon), the cook who persisted.","s":36},{"t":"Salmonella sources","d":"Poultry, EGGS, PET FOOD, live backyard poultry, PEANUT BUTTER, sushi-grade seafood; produce recalls (watermelon, onions, cantaloupe, cucumbers, jalapenos).","s":36},{"t":"Campylobacter jejuni","d":"A LEADING cause of bacterial diarrhea in the United States, esp. children; rapid fever, headache, dizziness, BLOODY diarrhea; infectious dose <500 cells (ONE DROP of raw poultry fluid); under-reported.","s":36},{"t":"Listeria monocytogenes","d":"Birds, mammals, SOIL; big recalls (ice cream, cantaloupe, frozen vegetables); PREGNANT women, unborn and premature babies, elderly, immunocompromised; slide: #1 cause of food-related DEATHS in the United States.","s":37},{"t":"Listeria foods","d":"Soft cheeses, deli meats, hot dogs, raw produce, raw meat, smoked seafood. Grows from 1 to 40 °C: FRIDGE, room and freezer temperatures. Spreads to brain and across the placenta to the fetus.","s":37},{"t":"Clostridium","d":"Gram-positive rods, STRICT ANAEROBES, SPORES (soil, plants, HONEY). Food: botulinum, perfringens. Not food: tetani, difficile.","s":37},{"t":"Botulism","d":"Toxin made when spores GERMINATE; foodborne and wound botulism; paralysis with muscles RELAXED → respiratory failure; a few bacteria make plenty of toxin.","s":37},{"t":"Bacillus cereus","d":"Very common, SUMMER; DIARRHEAL (meat) or EMETIC (rice); onset ≤6 hours; self-resolving vomiting and cramps; hot foods hot, cold foods cold.","s":37},{"t":"Vibrio","d":"cholerae, vulnificus, parahaemolyticus; SALT-tolerant, ocean and estuarine water; WATER (ingested, WOUNDS) or FOOD (shellfish, oysters, crabs, raw seafood); the R-month rule is now uncertain.","s":37},{"t":"Protozoa","d":"Cryptosporidium, Cyclospora, Giardia, Entamoeba: mild, self-limiting diarrhea from uncooked fruit and vegetables or DRINKING WATER; ready-to-eat SALAD BAGS.","s":38},{"t":"Worms","d":"Tapeworm, roundworm, trichinosis: killed by THOROUGH COOKING; venison and pork infected while the animal is ALIVE; pet feces.","s":38},{"t":"Norovirus","d":"Norwalk-like, Caliciviridae; person to person by FECES and VOMITUS (daycares, nursing homes, CRUISE SHIPS); shellfish; a FEW particles infect; rapid onset, short course.","s":38},{"t":"Hepatitis A and E","d":"FECAL-ORAL; most contagious ~2 WEEKS BEFORE symptoms; NOT kissing, sneezing, saliva or blood; vaccine after suspected exposure; handwashing, diaper hygiene.","s":38},{"t":"PulseNet","d":"Each isolate's PULSED-FIELD GEL ELECTROPHORESIS pattern → the Centers for Disease Control and Prevention database. Finds outbreak causes and processing-plant problems; cuts DETECTION TIME and NUMBER OF CASES.","s":39},{"t":"Matching patterns","d":"The slide 34 gel: patient, environmental and animal E. coli O157 isolates share one pattern.","s":39},{"t":"Recall sources","d":"Food and Drug Administration (food, dietary supplements, PET FOOD) · United States Department of Agriculture · Foodsafetynews.com, Foodsafetymagazine.com.","s":39},{"t":"Objective 3","d":"Antibiotic resistance in the food supply: NO SLIDE covers it. Not quizzed; listen for it in the recording.","s":39},{"t":"What you can do","d":"Hot soapy handwashing · wash produce · when in doubt, toss it out · mild bleach on surfaces · meat thermometer 165 °F · no cross-contamination of boards · gloves, hair coverings · ServSafe.","s":39}],"map":{"microbiology-exam-3-food-safety-quiz-version-2":[185,187,179,54,197,196,190,50,53,204,195,202,55,193,203,192,50,67,65,193,187,193,182,181,194,57,64,70,52,200],"microbiology-exam-3-food-safety-quiz":[193,50,-1,69,189,180,200,187,55,180,199,189,192,54,201,192,194,184,196,186,197,205,51,66,203,201,200,46,52,187],"microbiology-exam-3-fungi-of-medical-importance-quiz-version-2":[-1,166,154,168,9,157,158,35,158,167,33,153,206,143,6,150,22,38,139,-1,167,27,137,145,155,163,13,34,153,163],"microbiology-exam-3-fungi-of-medical-importance-quiz":[152,167,17,164,15,146,-1,148,154,157,171,153,141,35,165,3,169,23,1,161,7,149,31,12,135,16,147,35,165,-1],"microbiology-exam-3-gram-negative-bacilli-quiz-version-2":[107,116,119,124,106,103,100,87,83,109,96,132,97,94,120,114,108,-1,122,-1,82,127,72,90,117,126,111,50,78,-1],"microbiology-exam-3-gram-negative-bacilli-quiz":[106,109,85,108,105,97,124,86,115,99,189,185,119,87,97,91,73,116,189,124,112,128,107,73,98,91,118,120,107,-1]}};
